function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // draw clock for time, 168 hours = 7 days
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  // draw clock hands
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 40 * Math.sin(t), H/2 - 40 * Math.cos(t));
  ctx.stroke();
  // draw 7 lines for 7 days
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 + 30 * Math.cos(2 * Math.PI * i / 7), H/2 + 30 * Math.sin(2 * Math.PI * i / 7));
    ctx.lineTo(W/2 + 50 * Math.cos(2 * Math.PI * i / 7), H/2 + 50 * Math.sin(2 * Math.PI * i / 7));
    ctx.stroke();
  }
  ctx.restore();
}
